export function showInvoicePreviewModal(doc) {
  if (!doc) return;

  // Ensure customer details exist
  if (!doc.c) {
    const party = doc.party ? db.parties.find(p => p.id === doc.party) : null;
    doc.c = {
      n: party ? party.name : (doc.desc || 'Customer'),
      p: party?.phone || '',
      g: party?.gstin || '',
      s: party?.state || db.biz.state || 'Odisha',
      a: party?.addr || ''
    };
  }

  // Ensure line items exist
  if (!doc.lines || !doc.lines.length) {
    doc.lines = [{
      n: doc.desc || 'Scrap Material',
      h: '',
      q: 1,
      u: 'kg',
      r: (doc.base || doc.total || 0) / 100
    }];
  }

  // Remove any existing popup (and its listeners) first
  const oldModal = document.getElementById('pd_invoice_modal');
  if (oldModal) { oldModal._teardown ? oldModal._teardown() : oldModal.remove(); }

  const modalEl = document.createElement('div');
  modalEl.id = 'pd_invoice_modal';
  modalEl.className = 'pd-invoice-modal-overlay';

  const f = calcFigs(doc);
  const docTitle = f.m === 'none' ? 'Bill of Supply' : 'Tax Invoice';
  const custPhone = doc.c?.p || '';

  modalEl.innerHTML = `
    <div class="pd-invoice-card" role="dialog" aria-modal="true" aria-label="${docTitle} preview">
      <!-- Sticky header (hidden in print) -->
      <div class="pd-invoice-card-header noprint">
        <span class="pd-inv-badge">${docTitle} Preview &middot; #${esc(doc.no)}</span>
        <div class="pd-invoice-card-actions">
          <button type="button" class="pd-act-btn pd-act-primary pd-hide-sm" id="pd_modal_print" title="Print">${ICON_PRINT}<span class="pd-btn-label">Print</span></button>
          <button type="button" class="pd-act-btn pd-act-blue pd-hide-sm" id="pd_modal_pdf" title="Download PDF">${ICON_PDF}<span class="pd-btn-label">Download PDF</span></button>
          <button type="button" class="pd-act-btn pd-act-green pd-hide-sm" id="pd_modal_wa" title="Share on WhatsApp">${ICON_WA}<span class="pd-btn-label">WhatsApp</span></button>
          <button type="button" class="pd-act-btn pd-act-close" id="pd_modal_close" title="Close (Esc)" aria-label="Close">${ICON_X}</button>
        </div>
      </div>

      <!-- Invoice body -->
      <div class="pd-invoice-card-body">
        <div class="pd-invoice-sheet-wrap">
          ${renderSheet(doc)}
        </div>
      </div>

      <!-- Mobile sticky bottom action strip (under 640px) -->
      <div class="pd-inv-fab-bar noprint">
        <button type="button" class="pd-fab-btn pd-act-primary" id="pd_modal_print_mob">${ICON_PRINT}<span>Print</span></button>
        <button type="button" class="pd-fab-btn pd-act-blue" id="pd_modal_pdf_mob">${ICON_PDF}<span>PDF</span></button>
        <button type="button" class="pd-fab-btn pd-act-green" id="pd_modal_wa_mob">${ICON_WA}<span>WhatsApp</span></button>
      </div>
    </div>
  `;

  document.body.appendChild(modalEl);
  const prevOverflow = document.body.style.overflow;
  document.body.style.overflow = 'hidden'; // stop the page behind from scrolling

  const onKeyDown = (e) => { if (e.key === 'Escape') closeModal(); };
  document.addEventListener('keydown', onKeyDown);

  const teardown = () => {
    modalEl.remove();
    document.removeEventListener('keydown', onKeyDown);
    document.body.style.overflow = prevOverflow;
    const waGuide = document.getElementById('pd_wa_guide_modal');
    if (waGuide) waGuide.remove();
  };
  modalEl._teardown = teardown;

  // Close -> reset to the Records tab and scroll to the list
  const closeModal = () => {
    teardown();
    salesState.tab = 'rec';
    salesState.editNo = null;
    salesState.selectedPartyId = null;
    salesState.lines = [];
    const container = $('#v');
    if (container) {
      container.innerHTML = renderSales();
      bindSalesEvents();
      container.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } else {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // Print
  const handlePrint = () => window.print();
  ['#pd_modal_print', '#pd_modal_print_mob'].forEach(id => {
    const el = modalEl.querySelector(id);
    if (el) el.onclick = handlePrint;
  });

  // PDF Download
  const handlePdf = () => {
    try {
      const p = mkPdf(doc);
      const name = ('Invoice_' + doc.no + '_' + (doc.c?.n || 'Customer')).replace(/[^\w.-]+/g, '_') + '.pdf';
      p.save(name);
      toast('PDF downloaded');
    } catch (e) {
      console.error(e);
      toast('PDF error — using print dialog instead');
      window.print();
    }
  };
  ['#pd_modal_pdf', '#pd_modal_pdf_mob'].forEach(id => {
    const el = modalEl.querySelector(id);
    if (el) el.onclick = handlePdf;
  });

  // Helper guidance modal for WhatsApp Desktop / Web sharing
  const showWaHelperModal = ({ docNo, customerName, phone, fileName, waUrl, fullMsg, onRedownload }) => {
    const existing = document.getElementById('pd_wa_guide_modal');
    if (existing) existing.remove();

    const overlay = document.createElement('div');
    overlay.className = 'pd-wa-modal-overlay noprint';
    overlay.id = 'pd_wa_guide_modal';
    overlay.innerHTML = `
      <div class="pd-wa-card" role="dialog" aria-modal="true" aria-label="WhatsApp Sharing Guide">
        <div class="pd-wa-header">
          <div class="pd-wa-icon-badge">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2">
              <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/>
            </svg>
          </div>
          <div style="flex:1;min-width:0;">
            <h3 style="margin:0;font-size:16px;font-weight:700;color:#0f172a;">Sharing to WhatsApp</h3>
            <p style="margin:2px 0 0;font-size:12.5px;color:#64748b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
              ${esc(customerName)} &bull; #${esc(docNo)} ${phone ? `&bull; +${phone.length === 10 ? '91 ' + phone : phone}` : ''}
            </p>
          </div>
          <button type="button" class="universal-close-btn" id="pd_wa_close_x" aria-label="Close" style="background:none;border:none;cursor:pointer;color:#64748b;padding:4px;">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
          </button>
        </div>

        <div style="padding:16px 20px;">
          <div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:12px;">
            <span style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:#ecfdf5;color:#059669;font-weight:700;font-size:12px;flex-shrink:0;">✓</span>
            <div style="font-size:13px;color:#334155;line-height:1.45;">
              <b>WhatsApp chat opened with invoice breakdown:</b>
              <div style="font-size:12px;color:#64748b;margin-top:2px;">
                Complete bill breakdown, items and totals are pre-filled in your WhatsApp message.
              </div>
            </div>
          </div>

          <div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:14px;">
            <span style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:#eff6ff;color:#2563eb;font-weight:700;font-size:12px;flex-shrink:0;">📥</span>
            <div style="font-size:13px;color:#334155;line-height:1.45;min-width:0;flex:1;">
              <b>Official PDF document downloaded (single clean file):</b>
              <div style="display:inline-flex;align-items:center;gap:6px;background:#f8fafc;border:1px solid #e2e8f0;padding:4px 8px;border-radius:6px;font-family:monospace;font-size:11.5px;color:#1e293b;margin-top:4px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
                📄 ${esc(fileName)}
              </div>
            </div>
          </div>

          <div style="background:#fffbeb;border:1px solid #fef3c7;border-radius:8px;padding:12px;font-size:12.5px;color:#92400e;line-height:1.5;">
            💡 <b>How to send PDF document with text:</b>
            <div style="margin-top:4px;font-size:12px;line-height:1.5;">
              • The official PDF (<b>${esc(fileName)}</b>) has been downloaded to your computer and the summary copied to clipboard.<br>
              • Drag or attach the file into your WhatsApp chat, and paste (Cmd+V / Ctrl+V) the message caption.
            </div>
          </div>
        </div>

        <div style="display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:12px 20px;border-top:1px solid #f1f5f9;background:#f8fafc;flex-wrap:wrap;">
          <button type="button" class="btn alt sm" id="pd_wa_copy_btn" style="font-size:12px;">📋 Copy Text</button>
          <button type="button" class="btn alt sm" id="pd_wa_redownload_btn" style="font-size:12px;">📥 Re-download PDF</button>
          <button type="button" class="btn green sm" id="pd_wa_reopen_btn" style="font-size:12px;background:#25D366;color:#fff;border:none;">💬 Open WhatsApp</button>
          <button type="button" class="btn pri sm" id="pd_wa_done_btn" style="font-size:12px;">Done</button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);

    const close = () => overlay.remove();
    overlay.querySelector('#pd_wa_close_x').onclick = close;
    overlay.querySelector('#pd_wa_done_btn').onclick = close;
    overlay.querySelector('#pd_wa_reopen_btn').onclick = () => window.open(waUrl, '_blank');
    overlay.querySelector('#pd_wa_copy_btn').onclick = () => {
      if (navigator.clipboard && navigator.clipboard.writeText && fullMsg) {
        navigator.clipboard.writeText(fullMsg);
        toast('Invoice summary copied to clipboard');
      }
    };
    overlay.querySelector('#pd_wa_redownload_btn').onclick = () => {
      if (typeof onRedownload === 'function') onRedownload();
    };
  };

  // WhatsApp Share with PDF & Text
  const handleWa = async () => {
    const waBtns = ['#pd_modal_wa', '#pd_modal_wa_mob'].map(sel => modalEl.querySelector(sel)).filter(Boolean);
    const origHtmls = waBtns.map(b => b.innerHTML);
    waBtns.forEach(b => {
      b.disabled = true;
      b.innerHTML = `<span style="font-size:12px;display:inline-flex;align-items:center;gap:4px;">⏳ Preparing...</span>`;
    });

    const resetBtns = () => {
      waBtns.forEach((b, i) => {
        b.disabled = false;
        b.innerHTML = origHtmls[i];
      });
    };

    try {
      const bizName = db.biz.name || 'PD ENTERPRISES';
      const cName = doc.c?.n || 'Customer';
      const gt = inr(f.gt);
      const bal = inr(f.bal);
      const dateStr = doc.date ? doc.date.split('-').reverse().join('/') : '';
      const linesSummary = (doc.lines || []).map(l =>
        `• ${l.n}: ${l.q} ${l.u || 'kg'} @ Rs.${(+l.r).toFixed(2)} = Rs.${((l.q || 0) * (l.r || 0)).toFixed(2)}`
      ).join('\n');

      let baseMsg = `*${docTitle.toUpperCase()} - ${doc.no}*\n*${bizName}*\n\nDate: ${dateStr}\nCustomer: ${cName}${doc.veh ? '\nVehicle: ' + doc.veh : ''}\n\n*Items:*\n${linesSummary}\n\n*Total Amount:* ${gt}\n*Received:* ${inr(f.rec)}\n*Balance Due:* ${bal}`;

      // 1. Generate the official PDF
      let p = null;
      let pdfBlob = null;
      let pdfFile = null;
      const baseFileName = ('Invoice_' + doc.no + '_' + cName).replace(/[^\w.-]+/g, '_');
      const pdfFileName = baseFileName + '.pdf';

      try {
        p = mkPdf(doc);
        pdfBlob = p.output('blob');
        pdfFile = new File([pdfBlob], pdfFileName, { type: 'application/pdf' });
      } catch (err) {
        console.warn('Could not generate PDF object:', err);
      }

      // 2. Build complete message text (pure text breakdown - no remote PDF uploads or db storage)
      const fullMsg = baseMsg + '\n\nThank you for your business!';

      // 3. Mobile Devices ONLY (Android / iOS phones & tablets):
      // Web Share API Level 2 cleanly attaches 1 file with caption on mobile OSs.
      // On desktop (macOS / Windows), navigator.share is deliberately NOT used because
      // macOS Chrome's WebShare bridge causes duplicate attachments and prepends temp file paths.
      const isMobileDevice = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent) || 
        (navigator.maxTouchPoints > 1 && !/Macintosh/i.test(navigator.userAgent));

      if (isMobileDevice && pdfFile && navigator.canShare && navigator.canShare({ files: [pdfFile] })) {
        try {
          // Pass ONLY files and text (NO title property to prevent duplicate file attachments)
          await navigator.share({
            files: [pdfFile],
            text: fullMsg
          });
          toast('Shared invoice via system share');
          resetBtns();
          return;
        } catch (err) {
          if (err.name === 'AbortError') {
            resetBtns();
            return;
          }
          console.warn('Native mobile share failed, falling back to direct WhatsApp URL:', err);
        }
      }

      // 4. Desktop (Mac / Windows) direct WhatsApp workflow:
      // Download single PDF file automatically to Downloads purely client-side
      if (p) {
        try {
          p.save(pdfFileName);
          toast(`PDF downloaded: ${pdfFileName}`);
        } catch (e) {
          console.warn('Could not trigger automatic PDF save:', e);
        }
      }

      // Copy complete invoice summary to clipboard so user can effortlessly paste into WhatsApp
      if (navigator.clipboard && navigator.clipboard.writeText) {
        try {
          await navigator.clipboard.writeText(fullMsg);
        } catch (e) {}
      }

      // Open WhatsApp directly to the customer's chat with formatted text
      const cleanPhone = custPhone.replace(/\D/g, '');
      const waUrl = cleanPhone
        ? `https://wa.me/${cleanPhone.length === 10 ? '91' + cleanPhone : cleanPhone}?text=${encodeURIComponent(fullMsg)}`
        : `https://api.whatsapp.com/send?text=${encodeURIComponent(fullMsg)}`;
      window.open(waUrl, '_blank');

      // 5. Display a sleek guidance modal on desktop
      showWaHelperModal({
        docNo: doc.no,
        customerName: cName,
        phone: cleanPhone,
        fileName: pdfFileName,
        waUrl: waUrl,
        fullMsg: fullMsg,
        onRedownload: () => {
          if (p) {
            p.save(pdfFileName);
            toast('PDF downloaded again');
          }
        }
      });

    } catch (e) {
      console.error('WhatsApp share error:', e);
      toast('Could not share on WhatsApp: ' + (e?.message || e));
    } finally {
      resetBtns();
    }
  };
  ['#pd_modal_wa', '#pd_modal_wa_mob'].forEach(id => {
    const el = modalEl.querySelector(id);
    if (el) el.onclick = handleWa;
  });

  const closeBtn = modalEl.querySelector('#pd_modal_close');
  if (closeBtn) closeBtn.onclick = closeModal;
}

/* ================= SALES INVOICE VIEW RENDERER ================= */
export function renderSales() {
  const currentTab = salesState.tab;
  const scrapItems = db.items || [];
  const sales = db.docs.filter(d => d.type === 'sale').reverse();

  // Stats calculation
  const totalInvoices = sales.length;
  const thisMonthStr = today().slice(0, 7);
  const thisMonthTotal = sales.filter(d => (d.date || '').startsWith(thisMonthStr) && !d.cancelled).reduce((s, d) => s + (d.total || 0), 0);
  const totalBilled = sales.filter(d => !d.cancelled).reduce((s, d) => s + (d.total || 0), 0);
  const totalPending = sales.filter(d => !d.cancelled).reduce((s, d) => s + out(d), 0);

  // Search filter in Records
  const qLower = (salesState.q || '').toLowerCase();
  const filteredSales = sales.filter(d => {
    const cust = d.c?.n || pn(d.party) || '';
    const no = d.no || '';
    const veh = d.veh || '';
    return (no + ' ' + cust + ' ' + veh).toLowerCase().includes(qLower);
  });

  // Prepare active object for editing or fresh
  let activeInv;
  if (salesState.editNo) {
    activeInv = db.docs.find(d => d.no === salesState.editNo && d.type === 'sale');
  }

  const customers = db.parties.filter(isC);
  let activeParty = null;
  if (salesState.selectedPartyId) {
    activeParty = db.parties.find(p => p.id === salesState.selectedPartyId);
  } else if (activeInv && activeInv.party) {
    activeParty = db.parties.find(p => p.id === activeInv.party);
    if (activeParty) salesState.selectedPartyId = activeParty.id;
  }
  const activeCustomerId = activeParty ? activeParty.id : (salesState.selectedPartyId || '');

  const invNo = activeInv ? activeInv.no : (salesState.newNo || nextInvNo());
  const invDate = activeInv ? activeInv.date : today();
  const invVeh = activeInv ? (activeInv.veh || '') : '';
  const custName = activeParty ? activeParty.name : (activeInv ? (activeInv.c?.n || pn(activeInv.party) || '') : '');
  const custPhone = activeParty ? (activeParty.phone || '') : (activeInv ? (activeInv.c?.p || '') : '');
  const custGstin = activeParty ? (activeParty.gstin || '') : (activeInv ? (activeInv.c?.g || '') : '');
  const custState = activeParty ? (activeParty.state || db.biz.state || 'Odisha') : (activeInv ? (activeInv.c?.s || db.biz.state || 'Odisha') : (db.biz.state || 'Odisha'));
  const custAddr = activeParty ? (activeParty.addr || '') : (activeInv ? (activeInv.c?.a || '') : '');
  const invDisc = activeInv ? (activeInv.disc || 0) : 0;
  const invRate = activeInv ? (activeInv.rate !== undefined ? activeInv.rate : 18) : 18;
  const invMode = activeInv ? (activeInv.modeSel || 'auto') : 'auto';
  const isPaymentReceived = salesState.paymentReceived !== undefined
    ? salesState.paymentReceived
    : (activeInv ? Boolean((activeInv.paid || 0) > 0 || (activeInv.pays && activeInv.pays.length > 0)) : false);
  const invPaid = activeInv ? (activeInv.paid || 0) : (isPaymentReceived ? (salesState.invPaid || '') : 0);
  const invPm = activeInv ? (activeInv.pm || 'Cash') : 'Cash';
  const invDepositAcct = activeInv ? (activeInv.payAcct || (invPm === 'Cash' ? '1000' : '1010')) : '1000';
  const invPayRef = activeInv ? (activeInv.payRef || '') : '';
  const invNotes = activeInv ? (activeInv.nt || '') : '';

  // Current lines
  const lines = salesState.lines.length ? salesState.lines : [{ n: 'Iron scrap', h: '7204', q: 100, u: 'kg', r: 28 }];
  salesState.lines = lines;

  // Compute live totals for the new invoice form
  const curObj = {
    no: invNo,
    date: invDate,
    veh: invVeh,
    c: { n: custName, p: custPhone, g: custGstin, s: custState, a: custAddr },
    lines,
    disc: invDisc,
    rate: invRate,
    mode: getMode(custState, invMode, invRate, custGstin),
    paid: isPaymentReceived ? (parseFloat(invPaid) || 0) : 0,
    pm: invPm,
    nt: invNotes
  };
  const liveFigs = calcFigs(curObj);

  return `
    <div class="pd-sales-page">
    ${head('Sales Invoices', `<button class="p" id="pd_head_add">${currentTab === 'new' ? 'View records' : (currentTab === 'itm' ? '+ Add item' : '+ New invoice')}</button>`)}

    <div class="pd-nav-tabs noprint">
      <button type="button" class="${currentTab === 'new' && !salesState.editNo ? 'on' : ''}" data-st="new">
        New invoice
      </button>
      <button type="button" class="${currentTab === 'rec' ? 'on' : ''}" data-st="rec">
        Records (${totalInvoices})
      </button>
      <button type="button" class="${currentTab === 'itm' ? 'on' : ''}" data-st="itm">
        Scrap items
      </button>
      ${currentTab === 'view' ? `<button type="button" class="on" data-st="view">Invoice Preview</button>` : ''}
    </div>

    <!-- TAB 1: NEW / EDIT INVOICE -->
    <div id="pd-tab-new" style="display:${currentTab === 'new' ? 'block' : 'none'}">
      <div class="pd-card">
        ${salesState.editNo ? `
          <div style="display:flex;justify-content:space-between;align-items:center;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:12px 16px;margin-bottom:18px;flex-wrap:wrap;gap:10px;">
            <div style="display:flex;align-items:center;gap:10px;">
              <span style="background:#2563eb;color:#fff;font-size:11px;font-weight:700;padding:2px 8px;border-radius:4px;text-transform:uppercase;">Edit Mode</span>
              <h3 style="margin:0;font-size:16px;color:#1e40af;">Editing Invoice: <b>${esc(salesState.editNo)}</b></h3>
            </div>
            <div class="pd-btn-row" style="margin:0;gap:8px;">
              <button type="button" class="btn p sm" id="pd_btn_save_top">Update Invoice</button>
              <button type="button" class="btn alt sm" id="pd_btn_cancel_top">Cancel</button>
              <button type="button" class="btn alt sm" id="pd_btn_back_rec">← Back to Records</button>
            </div>
          </div>
        ` : `
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:10px;">
            <h3 style="margin:0;">New Invoice</h3>
          </div>
        `}

        <!-- EXISTING PARTY SELECTION -->
        <div class="pd-party-selector" style="background:#f8fafc;border:1px solid var(--bd);border-radius:8px;padding:14px 16px;margin-bottom:20px;">
          <div style="display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;">
            <div style="flex:1;min-width:260px;">
              <label class="pd-label" style="font-weight:600;color:var(--tx);margin-bottom:6px;">
                Select Existing Customer
              </label>
              <select id="pd_sel_customer" style="width:100%;padding:8px 12px;border:1px solid var(--bd);border-radius:6px;background:#fff;font-size:14px;font-weight:500;">
                <option value="">-- Choose from existing customers --</option>
                ${customers.map(p => `<option value="${p.id}" ${p.id === activeCustomerId ? 'selected' : ''}>${esc(p.name)}${p.phone ? ' (' + esc(p.phone) + ')' : ''}${p.state ? ' · ' + esc(p.state) : ''}</option>`).join('')}
                <option value="__NEW__">➕ + Add New Customer...</option>
              </select>
            </div>
            <div style="display:flex;align-items:flex-end;padding-top:18px;">
              <button type="button" class="p" id="pd_btn_new_cust" style="padding:8px 16px;font-size:13px;font-weight:600;white-space:nowrap;">
                + Add Customer
              </button>
            </div>
          </div>
        </div>

        <div class="pd-grid">
          <label class="pd-label">Invoice no.
            <input type="text" id="pd_no" value="${esc(invNo)}">
          </label>
          <label class="pd-label">Date
            <input type="date" id="pd_dt" value="${esc(invDate)}">
          </label>
          <label class="pd-label">Vehicle no.
            <input type="text" id="pd_veh" placeholder="OD 01 AB 1234" value="${esc(invVeh)}">
          </label>
          <label class="pd-label">Customer name *
            <input type="text" id="pd_cn" list="pd_cl" value="${esc(custName)}" placeholder="Customer / Business name">
            <datalist id="pd_cl">
              ${customers.map(p => `<option value="${esc(p.name)}">`).join('')}
            </datalist>
          </label>
          <label class="pd-label">Phone
            <input type="text" id="pd_cp" value="${esc(custPhone)}" placeholder="Phone number">
          </label>
          <label class="pd-label">Customer GSTIN (optional)
            <input type="text" id="pd_cg" style="text-transform:uppercase" value="${esc(custGstin)}" placeholder="e.g. 21AAAAA0000A1Z5">
          </label>
          <label class="pd-label">State
            <input type="text" id="pd_cs" value="${esc(custState)}" placeholder="State (e.g. Odisha)">
          </label>
          <label class="pd-label" style="grid-column:1/-1">Address
            <input type="text" id="pd_ca" value="${esc(custAddr)}" placeholder="Customer billing address">
          </label>
        </div>
      </div>

      <div class="pd-card">
        <h3>Scrap items</h3>
        <div class="pd-table-wrap">
          <table class="pd-table pd-scrap-lines-table">
            <thead>
              <tr>
                <th style="min-width:160px">Item</th>
                <th style="width:100px">HSN</th>
                <th style="width:110px">Qty</th>
                <th style="width:110px">Unit</th>
                <th style="width:120px">Rate (₹)</th>
                <th style="width:120px;text-align:right">Amount</th>
                <th style="width:40px"></th>
              </tr>
            </thead>
            <tbody id="pd_lines">
              ${lines.map((l, i) => `
                <tr data-line="${i}" data-prev-unit="${esc(l.u || 'kg')}">
                  <td data-label="Item">
                    <select class="pd-line-name" data-i="${i}">
                      <option value="">Custom…</option>
                      ${scrapItems.map(x => `<option value="${esc(x.n)}" ${x.n === l.n ? 'selected' : ''}>${esc(x.n)}</option>`).join('')}
                    </select>
                  </td>
                  <td data-label="HSN">
                    <input type="text" class="pd-line-hsn" data-i="${i}" value="${esc(l.h || '')}">
                  </td>
                  <td data-label="Qty">
                    <input type="number" step="any" min="0" class="pd-line-qty" data-i="${i}" value="${l.q ?? ''}">
                  </td>
                  <td data-label="Unit">
                    <select class="pd-line-unit" data-i="${i}">
                      ${['kg', 'quintal', 'ton', 'pcs'].map(u => `<option value="${u}" ${u === (l.u || 'kg') ? 'selected' : ''}>${u}</option>`).join('')}
                    </select>
                  </td>
                  <td data-label="Rate (₹)">
                    <input type="number" step="any" min="0" class="pd-line-rate" data-i="${i}" value="${l.r ?? ''}">
                  </td>
                  <td data-label="Amount" style="text-align:right;font-weight:600">
                    ${inr((parseFloat(l.q) || 0) * (parseFloat(l.r) || 0))}
                  </td>
                  <td data-label="Actions">
                    <button type="button" class="btn red sm pd-line-del" data-i="${i}" title="Remove line" aria-label="Remove item"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="pointer-events:none"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></button>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
        <div class="pd-btn-row">
          <button type="button" class="btn alt sm" id="pd_add_line">+ Add line</button>
        </div>
      </div>

      <div class="pd-card">
        <div class="pd-grid">
          <label class="pd-label">Tax type
            <select id="pd_mode">
              <option value="auto" ${invMode === 'auto' ? 'selected' : ''}>Auto (by state)</option>
              <option value="intra" ${invMode === 'intra' ? 'selected' : ''}>CGST + SGST</option>
              <option value="inter" ${invMode === 'inter' ? 'selected' : ''}>IGST</option>
              <option value="none" ${invMode === 'none' ? 'selected' : ''}>No GST (Bill of Supply)</option>
            </select>
          </label>
          <label class="pd-label">GST rate %
            <select id="pd_rate">
              <option value="0" ${+invRate === 0 ? 'selected' : ''}>0</option>
              <option value="5" ${+invRate === 5 ? 'selected' : ''}>5</option>
              <option value="12" ${+invRate === 12 ? 'selected' : ''}>12</option>
              <option value="18" ${+invRate === 18 ? 'selected' : ''}>18</option>
              <option value="28" ${+invRate === 28 ? 'selected' : ''}>28</option>
            </select>
          </label>
          <label class="pd-label">Discount (₹)
            <input type="number" id="pd_disc" value="${invDisc}" min="0">
          </label>
          <label class="pd-label">Notes
            <input type="text" id="pd_nt" value="${esc(invNotes)}">
          </label>
        </div>

        <!-- CONDITIONAL PAYMENT TOGGLE -->
        <div style="background:#f8fafc;border:1px solid var(--bd);border-radius:8px;padding:14px 16px;margin-top:16px;">
          <label style="display:flex;align-items:center;gap:10px;cursor:pointer;user-select:none;font-weight:600;font-size:14px;color:var(--tx);margin:0;">
            <input type="checkbox" id="pd_pay_received" ${isPaymentReceived ? 'checked' : ''} style="width:18px;height:18px;cursor:pointer;margin:0;">
            <span>Payment Received Now?</span>
          </label>
          <div id="pd_payment_fields" style="display:${isPaymentReceived ? 'grid' : 'none'};grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));gap:12px;margin-top:14px;padding-top:14px;border-top:1px dashed var(--bd);">
            <label class="pd-label">Amount received (₹)
              <input type="number" id="pd_paid" value="${invPaid}" min="0" step="any">
            </label>
            <label class="pd-label">Payment mode
              <select id="pd_pm">
                <option ${invPm === 'Cash' ? 'selected' : ''}>Cash</option>
                <option ${invPm === 'UPI' ? 'selected' : ''}>UPI</option>
                <option ${invPm === 'Bank transfer' ? 'selected' : ''}>Bank transfer</option>
                <option ${invPm === 'Cheque' ? 'selected' : ''}>Cheque</option>
              </select>
            </label>
            <label class="pd-label">Deposit Account
              <select id="pd_deposit_acct">
                <option value="1000" ${invDepositAcct === '1000' ? 'selected' : ''}>1000 · Cash in Hand</option>
                <option value="1010" ${invDepositAcct === '1010' ? 'selected' : ''}>1010 · Bank Account</option>
              </select>
            </label>
            <label class="pd-label">Payment Reference / Txn ID
              <input type="text" id="pd_pay_ref" value="${esc(invPayRef)}" placeholder="e.g. UPI Ref / Cheque No">
            </label>
          </div>
        </div>

        <div class="pd-tot" id="pd_totals_box" style="margin-top:16px">
          <div><span>Subtotal</span><span>${inr(liveFigs.sub)}</span></div>
          ${liveFigs.disc ? `<div><span>Discount</span><span>− ${inr(liveFigs.disc)}</span></div>` : ''}
          ${liveFigs.m === 'intra'
      ? `<div><span>CGST @ ${liveFigs.rt / 2}%</span><span>${inr(liveFigs.half)}</span></div><div><span>SGST @ ${liveFigs.rt / 2}%</span><span>${inr(liveFigs.half)}</span></div>`
      : liveFigs.m === 'inter'
        ? `<div><span>IGST @ ${liveFigs.rt}%</span><span>${inr(liveFigs.tax)}</span></div>`
        : ''}
          ${liveFigs.ro ? `<div><span>Round off</span><span>${inr(liveFigs.ro)}</span></div>` : ''}
          <div class="gt"><span>Total</span><span>${inr(liveFigs.gt)}</span></div>
          <div><span>Balance due</span><span>${inr(liveFigs.bal)}</span></div>
        </div>

        <div class="pd-btn-row" style="margin-top:16px">
          <button type="button" class="btn p" id="pd_btn_save">${salesState.editNo ? 'Update Invoice' : 'Save &amp; preview'}</button>
          <button type="button" class="btn alt" id="${salesState.editNo ? 'pd_btn_cancel_bottom' : 'pd_btn_clear'}">${salesState.editNo ? 'Cancel' : 'Clear form'}</button>
        </div>
      </div>
    </div>

    <!-- TAB 2: RECORDS -->
    <div id="pd-tab-rec" style="display:${currentTab === 'rec' ? 'block' : 'none'}">
      <div class="pd-stats">
        <div><span>Invoices</span><b>${totalInvoices}</b></div>
        <div><span>This month</span><b>${fmt(thisMonthTotal)}</b></div>
        <div><span>Total billed</span><b>${fmt(totalBilled)}</b></div>
        <div><span>Pending</span><b>${fmt(totalPending)}</b></div>
      </div>

      <div class="pd-card">
        <div class="pd-btn-row pd-search-toolbar" style="margin-bottom:12px;justify-content:space-between">
          <input type="text" id="pd_search_q" placeholder="Search customer, invoice no., vehicle" value="${esc(salesState.q)}" style="max-width:340px">
          <button type="button" class="btn alt" id="pd_btn_csv">Export CSV</button>
        </div>

        <div class="pd-table-wrap responsive-cards">
          <table class="pd-table">
            <thead>
              <tr>
                <th>Invoice</th>
                <th>Date</th>
                <th>Customer</th>
                <th>Vehicle</th>
                <th style="text-align:right">Total</th>
                <th>Status</th>
                <th style="text-align:right">Actions</th>
              </tr>
            </thead>
            <tbody>
              ${filteredSales.length ? filteredSales.map(d => {
          const f = calcFigs(d);
          const s = dstat(d);
          const isPaid = f.bal <= 0 || s[0] === 'Paid';
          const isPartial = !isPaid && (d.paid > 0 || (d.pays && d.pays.length > 0));
          const pillCls = isPaid ? '' : (isPartial ? 'p' : 'u');
          const pillTxt = isPaid ? 'Paid' : (isPartial ? 'Part paid' : 'Unpaid');

          return `<tr>
                  <td data-label="Invoice"><b>${esc(d.no)}</b></td>
                  <td data-label="Date">${d.date ? d.date.split('-').reverse().join('/') : ''}</td>
                  <td data-label="Customer">${esc(d.c?.n || pn(d.party))}</td>
                  <td data-label="Vehicle">${esc(d.veh || '')}</td>
                  <td data-label="Total" style="text-align:right;font-weight:600">${fmt(d.total)}</td>
                  <td data-label="Status"><span class="pd-pill ${pillCls}">${pillTxt}</span></td>
                  <td data-label="Actions" style="text-align:right">
                    <div class="pd-btn-row desktop-actions sales-desktop-actions" style="justify-content:flex-end">
                      <button type="button" class="sales-icon-btn sales-btn-view" data-action="view" data-no="${esc(d.no)}" title="View Invoice" aria-label="View Invoice">
                        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"></path><circle cx="12" cy="12" r="3"></circle></svg>
                      </button>
                      <button type="button" class="sales-icon-btn sales-btn-edit" data-action="edit" data-no="${esc(d.no)}" title="Edit Invoice" aria-label="Edit Invoice">
                        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"></path></svg>
                      </button>
                      ${!isPaid && !d.cancelled ? `
                        <button type="button" class="sales-icon-btn sales-btn-pay" data-action="pay" data-no="${esc(d.no)}" title="Mark as Paid" aria-label="Mark as Paid">
                          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="m9 12 2 2 4-4"></path></svg>
                        </button>
                      ` : ''}
                      <button type="button" class="sales-icon-btn sales-btn-del" data-action="del" data-no="${esc(d.no)}" title="Delete Invoice" aria-label="Delete Invoice">
                        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
                      </button>
                    </div>
                    <button type="button" class="pd-more-btn" data-action="more" data-no="${esc(d.no)}" data-id="${esc(d.id)}" title="Actions" aria-label="Actions">⋮</button>
                  </td>
                </tr>`;
        }).join('') : `<tr><td colspan="7" style="text-align:center;color:var(--t2);padding:24px">No invoices found. Click "New invoice" to create one.</td></tr>`}
            </tbody>
          </table>
        </div>
      </div>
    </div>

    <!-- TAB 3: SCRAP ITEMS CATALOG -->
    <div id="pd-tab-itm" style="display:${currentTab === 'itm' ? 'block' : 'none'}">
      <div class="pd-card">
        <h3>Scrap item list &amp; default rates</h3>
        <p style="color:var(--t2);margin-top:-6px;font-size:13px">
          These scrap items appear in the invoice dropdown to automatically fill HSN code, unit and default rate.
        </p>
        <div class="pd-table-wrap pd-scrap-catalog-wrap">
          <table class="pd-table pd-scrap-catalog-table">
            <thead>
              <tr>
                <th>Item name</th>
                <th>HSN</th>
                <th>Unit</th>
                <th>Rate (₹)</th>
                <th style="width:40px"></th>
              </tr>
            </thead>
            <tbody id="pd_items_body">
              ${scrapItems.map((x, i) => `
                <tr>
                  <td data-label="Item"><input type="text" class="pd-item-n" data-i="${i}" value="${esc(x.n)}"></td>
                  <td data-label="HSN"><input type="text" class="pd-item-h" data-i="${i}" value="${esc(x.h)}"></td>
                  <td data-label="Unit">
                    <select class="pd-item-u" data-i="${i}">
                      ${['kg', 'quintal', 'ton', 'pcs'].map(u => `<option value="${u}" ${u === x.u ? 'selected' : ''}>${u}</option>`).join('')}
                    </select>
                  </td>
                  <td data-label="Rate (₹)"><input type="number" step="any" class="pd-item-r" data-i="${i}" value="${x.r}"></td>
                  <td data-label="Actions"><button type="button" class="btn red sm pd-item-del" data-i="${i}" title="Remove item" aria-label="Remove item"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="pointer-events:none"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></button></td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
        <div class="pd-btn-row pd-scrap-actions-row">
          <button type="button" class="btn alt" id="pd_btn_add_item">+ Add item</button>
          <button type="button" class="btn p" id="pd_btn_save_items">Save items</button>
        </div>
      </div>
    </div>

    <!-- TAB 4: A4 SHEET PREVIEW -->
    <div id="pd-tab-view" style="display:${currentTab === 'view' ? 'block' : 'none'}">
      <div class="noprint pd-btn-row" style="max-width:210mm;margin:0 auto 16px;justify-content:space-between">
        <button type="button" class="btn alt" id="pd_btn_back">&larr; Back to records</button>
        <div class="pd-btn-row">
          <button type="button" class="btn p" id="pd_btn_dpdf">Download PDF</button>
          <button type="button" class="btn alt" id="pd_btn_dhtml">Download HTML file</button>
          <button type="button" class="btn alt" id="pd_btn_print">Print</button>
        </div>
      </div>
      <div id="pd_sheet_container">
        ${salesState.viewNo ? renderSheet(db.docs.find(d => d.no === salesState.viewNo && d.type === 'sale') || curObj) : ''}
      </div>
    </div>
  </div>
  `;
}

/* ================= BIND EVENT LISTENERS ================= */
export function bindSalesEvents() {
  const container = $('#v');
  if (!container) return;

  // Top-Right Header Button (+ New invoice / View records / + Add item)
  const headAddBtn = $('#pd_head_add');
  if (headAddBtn) {
    headAddBtn.onclick = () => {
      if (salesState.tab === 'itm') {
        const addItemBtn = $('#pd_btn_add_item');
        if (addItemBtn) {
          addItemBtn.click();
        } else {
          if (!db.items) db.items = [];
          db.items.push({ n: '', h: '7204', u: 'kg', r: 0 });
          container.innerHTML = renderSales();
          bindSalesEvents();
        }
      } else if (salesState.tab === 'new') {
        salesState.tab = 'rec';
        salesState.editNo = null;
        container.innerHTML = renderSales();
        bindSalesEvents();
      } else {
        salesState.tab = 'new';
        salesState.editNo = null;
        salesState.selectedPartyId = null;
        salesState.lines = [];
        salesState.paymentReceived = false;
        salesState.newNo = nextInvNo();
        container.innerHTML = renderSales();
        bindSalesEvents();
      }
    };
  }

  // Tab switching
  container.querySelectorAll('[data-st]').forEach(btn => {
    btn.onclick = () => {
      salesState.tab = btn.dataset.st;
      if (btn.dataset.st === 'new') {
        salesState.editNo = null;
        salesState.selectedPartyId = null;
        salesState.lines = [];
        salesState.paymentReceived = false;
        salesState.newNo = nextInvNo();
      }
      container.innerHTML = renderSales();
      bindSalesEvents();
    };
  });

  // Cancel edit buttons
  const cancelEdit = () => {
    salesState.editNo = null;
    salesState.selectedPartyId = null;
    salesState.lines = [];
    salesState.tab = 'rec';
    container.innerHTML = renderSales();
    bindSalesEvents();
  };
  const cancelTop = $('#pd_btn_cancel_top');
  if (cancelTop) cancelTop.onclick = cancelEdit;
  const backRec = $('#pd_btn_back_rec');
  if (backRec) backRec.onclick = cancelEdit;
  const cancelBottom = $('#pd_btn_cancel_bottom');
  if (cancelBottom) cancelBottom.onclick = cancelEdit;

  // Dynamic lines changes & calculations
  const recalculateForm = () => {
    const lines = [];
    container.querySelectorAll('#pd_lines tr').forEach((tr, i) => {
      const n = tr.querySelector('.pd-line-name')?.value || '';
      const h = tr.querySelector('.pd-line-hsn')?.value || '';
      const q = parseFloat(tr.querySelector('.pd-line-qty')?.value) || 0;
      const u = tr.querySelector('.pd-line-unit')?.value || 'kg';
      const r = parseFloat(tr.querySelector('.pd-line-rate')?.value) || 0;
      lines.push({ n, h, q, u, r });
      const amtCell = tr.children[5];
      if (amtCell) amtCell.textContent = inr(q * r);
    });
    salesState.lines = lines;

    const custState = $('#pd_cs')?.value || db.biz.state || 'Odisha';
    const invMode = $('#pd_mode')?.value || 'auto';
    const invRate = parseFloat($('#pd_rate')?.value) || 0;
    const payReceived = Boolean($('#pd_pay_received')?.checked);
    const paidInput = $('#pd_paid');
    let invPaid = payReceived ? (parseFloat(paidInput?.value) || 0) : 0;

    const custGstin = ($('#pd_cg')?.value || '').trim();
    let f = calcFigs({
      lines,
      disc: invDisc,
      rate: invRate,
      mode: getMode(custState, invMode, invRate, custGstin),
      paid: invPaid
    });

    if (payReceived && paidInput && paidInput.dataset.autoSync === '1') {
      paidInput.value = f.gt > 0 ? f.gt : '';
      invPaid = f.gt;
      f = calcFigs({
        lines,
        disc: invDisc,
        rate: invRate,
        mode: getMode(custState, invMode, invRate, custGstin),
        paid: invPaid
      });
    }

    const box = $('#pd_totals_box');
    if (box) {
      box.innerHTML = `
        <div><span>Subtotal</span><span>${inr(f.sub)}</span></div>
        ${f.disc ? `<div><span>Discount</span><span>− ${inr(f.disc)}</span></div>` : ''}
        ${f.m === 'intra'
          ? `<div><span>CGST @ ${f.rt / 2}%</span><span>${inr(f.half)}</span></div><div><span>SGST @ ${f.rt / 2}%</span><span>${inr(f.half)}</span></div>`
          : f.m === 'inter'
            ? `<div><span>IGST @ ${f.rt}%</span><span>${inr(f.tax)}</span></div>`
            : ''}
        ${f.ro ? `<div><span>Round off</span><span>${inr(f.ro)}</span></div>` : ''}
        <div class="gt"><span>Total</span><span>${inr(f.gt)}</span></div>
        <div><span>Balance due</span><span>${inr(f.bal)}</span></div>
      `;
    }
  };

  // Line item name dropdown change -> autofill HSN, Unit, and smart rate conversion
  container.querySelectorAll('.pd-line-name').forEach(sel => {
    sel.onchange = e => {
      const idx = e.target.dataset.i;
      const val = e.target.value;
      const m = (db.items || []).find(x => x.n === val);
      if (m && idx !== undefined) {
        const tr = container.querySelector(`tr[data-line="${idx}"]`);
        if (tr) {
          const hsnInput = tr.querySelector('.pd-line-hsn');
          const unitSelect = tr.querySelector('.pd-line-unit');
          const rateInput = tr.querySelector('.pd-line-rate');
          if (hsnInput) hsnInput.value = m.h || '';

          const masterUnit = m.u || 'kg';
          const masterRate = parseFloat(m.r) || 0;
          const currentUnit = unitSelect ? unitSelect.value : masterUnit;

          if (unitSelect) {
            if (currentUnit && currentUnit !== masterUnit && masterRate > 0) {
              if (rateInput) rateInput.value = convertRate(masterRate, masterUnit, currentUnit);
            } else {
              unitSelect.value = masterUnit;
              if (rateInput) rateInput.value = masterRate;
            }
            tr.dataset.prevUnit = unitSelect.value;
          }
        }
      }
      recalculateForm();
    };
  });

  // Line item unit dropdown change -> auto-convert rate based on unit conversion matrix
  container.querySelectorAll('.pd-line-unit').forEach(unitSelect => {
    unitSelect.onchange = e => {
      const tr = e.target.closest('tr');
      if (!tr) return;
      const newUnit = e.target.value;
      const prevUnit = tr.dataset.prevUnit || 'kg';
      const rateInput = tr.querySelector('.pd-line-rate');
      const currentRate = parseFloat(rateInput?.value) || 0;

      if (currentRate > 0) {
        const converted = convertRate(currentRate, prevUnit, newUnit);
        if (rateInput) rateInput.value = converted;
      } else {
        const itemName = tr.querySelector('.pd-line-name')?.value || '';
        const m = (db.items || []).find(x => x.n === itemName);
        if (m && m.r) {
          const converted = convertRate(m.r, m.u || 'kg', newUnit);
          if (rateInput) rateInput.value = converted;
        }
      }
      tr.dataset.prevUnit = newUnit;
      recalculateForm();
    };
  });

  // Inputs in lines table
  container.querySelectorAll('.pd-line-qty, .pd-line-rate, .pd-line-hsn').forEach(input => {
    input.oninput = recalculateForm;
  });

  // Delete line button
  container.querySelectorAll('.pd-line-del').forEach(btn => {
    btn.onclick = () => {
      const idx = parseInt(btn.dataset.i, 10);
      if (!isNaN(idx)) {
        salesState.lines.splice(idx, 1);
        if (!salesState.lines.length) salesState.lines = [{ n: '', h: '', q: 0, u: 'kg', r: 0 }];
        container.innerHTML = renderSales();
        bindSalesEvents();
      }
    };
  });

  // Add line button
  const addLineBtn = $('#pd_add_line');
  if (addLineBtn) {
    addLineBtn.onclick = () => {
      salesState.lines.push({ n: '', h: '', q: 0, u: 'kg', r: 0 });
      container.innerHTML = renderSales();
      bindSalesEvents();
    };
  }

  // Existing Customer dropdown
  const selCust = $('#pd_sel_customer');
  if (selCust) {
    selCust.onchange = () => {
      const val = selCust.value;
      if (val === '__NEW__') {
        selCust.value = salesState.selectedPartyId || '';
        partyForm(null, 'customer', newParty => {
          salesState.selectedPartyId = newParty.id;
          container.innerHTML = renderSales();
          bindSalesEvents();
          toast('Customer "' + newParty.name + '" added & selected');
        });
        return;
      }
      salesState.selectedPartyId = val || null;
      const p = db.parties.find(x => x.id === val);
      if (p) {
        if ($('#pd_cn')) $('#pd_cn').value = p.name;
        if ($('#pd_cp')) $('#pd_cp').value = p.phone || '';
        if ($('#pd_cg')) $('#pd_cg').value = p.gstin || '';
        if ($('#pd_cs')) $('#pd_cs').value = p.state || db.biz.state || 'Odisha';
        if ($('#pd_ca')) $('#pd_ca').value = p.addr || '';
        recalculateForm();
      }
    };
  }

  // Quick add customer button
  const btnNewCust = $('#pd_btn_new_cust');
  if (btnNewCust) {
    btnNewCust.onclick = () => {
      partyForm(null, 'customer', newParty => {
        salesState.selectedPartyId = newParty.id;
        container.innerHTML = renderSales();
        bindSalesEvents();
        toast('Customer "' + newParty.name + '" added & selected');
      });
    };
  }

  // Customer autofill on select / typing
  const cnInput = $('#pd_cn');
  if (cnInput) {
    cnInput.onchange = () => {
      const val = cnInput.value.trim().toLowerCase();
      const p = db.parties.find(x => x.name.trim().toLowerCase() === val && isC(x));
      if (p) {
        salesState.selectedPartyId = p.id;
        if ($('#pd_sel_customer')) $('#pd_sel_customer').value = p.id;
        if ($('#pd_cp')) $('#pd_cp').value = p.phone || '';
        if ($('#pd_cg')) $('#pd_cg').value = p.gstin || '';
        if ($('#pd_cs')) $('#pd_cs').value = p.state || db.biz.state || 'Odisha';
        if ($('#pd_ca')) $('#pd_ca').value = p.addr || '';
        recalculateForm();
      }
    };
  }

  const cgInput = $('#pd_cg');
  if (cgInput) {
    cgInput.oninput = () => {
      const val = cgInput.value.trim().toUpperCase();
      if (val.length >= 2 && /^\d{2}/.test(val)) {
        if (val.startsWith('21')) {
          if ($('#pd_cs') && (!$('#pd_cs').value || $('#pd_cs').value.trim() !== 'Odisha')) {
            $('#pd_cs').value = 'Odisha';
          }
        }
      }
      recalculateForm();
    };
  }

  const csInput = $('#pd_cs');
  if (csInput) {
    csInput.oninput = recalculateForm;
  }

  // Payment received checkbox & conditional fields
  const payRecChk = $('#pd_pay_received');
  const payFields = $('#pd_payment_fields');
  const paidInput = $('#pd_paid');
  const depositAcctSelect = $('#pd_deposit_acct');
  const pmSelect = $('#pd_pm');

  if (payRecChk) {
    payRecChk.onchange = () => {
      salesState.paymentReceived = payRecChk.checked;
      if (payRecChk.checked) {
        if (payFields) payFields.style.display = 'grid';
        if (paidInput) {
          paidInput.dataset.autoSync = '1';
          const custState = $('#pd_cs')?.value || db.biz.state || 'Odisha';
          const invMode = $('#pd_mode')?.value || 'auto';
          const invRate = parseFloat($('#pd_rate')?.value) || 0;
          const invDisc = parseFloat($('#pd_disc')?.value) || 0;
          const f = calcFigs({
            lines: salesState.lines,
            disc: invDisc,
            rate: invRate,
            mode: getMode(custState, invMode, invRate),
            paid: 0
          });
          paidInput.value = f.gt > 0 ? f.gt : '';
        }
      } else {
        if (payFields) payFields.style.display = 'none';
        if (paidInput) {
          delete paidInput.dataset.autoSync;
          paidInput.value = '0';
        }
      }
      recalculateForm();
    };
  }

  if (paidInput) {
    paidInput.oninput = () => {
      delete paidInput.dataset.autoSync;
      recalculateForm();
    };
  }

  if (pmSelect && depositAcctSelect) {
    pmSelect.onchange = () => {
      if (pmSelect.value === 'Cash') {
        depositAcctSelect.value = '1000';
      } else {
        depositAcctSelect.value = '1010';
      }
      recalculateForm();
    };
  }

  // Tax and form inputs changes
  ['pd_mode', 'pd_rate', 'pd_disc', 'pd_paid', 'pd_cs', 'pd_deposit_acct', 'pd_pay_ref'].forEach(id => {
    const el = $('#' + id);
    if (el) el.oninput = recalculateForm;
  });

  // Clear form
  const clearBtn = $('#pd_btn_clear');
  if (clearBtn) {
    clearBtn.onclick = () => {
      salesState.editNo = null;
      salesState.selectedPartyId = null;
      salesState.lines = [{ n: 'Iron scrap', h: '7204', q: 100, u: 'kg', r: 28 }];
      salesState.paymentReceived = false;
      salesState.newNo = nextInvNo();
      container.innerHTML = renderSales();
      bindSalesEvents();
    };
  }

  // Save & Preview / Update Invoice
  const handleSaveInvoice = () => {
    const no = ($('#pd_no')?.value || '').trim();
    const date = $('#pd_dt')?.value || today();
    const veh = ($('#pd_veh')?.value || '').trim();
    const cName = ($('#pd_cn')?.value || '').trim();
    const cPhone = ($('#pd_cp')?.value || '').trim();
    const cGstin = ($('#pd_cg')?.value || '').trim().toUpperCase();
    const cState = ($('#pd_cs')?.value || db.biz.state || 'Odisha').trim();
    const cAddr = ($('#pd_ca')?.value || '').trim();

    if (!no) return toast('Invoice number is required');
    if (!cName) return toast('Customer name is required');
    if (cGstin && !/^\d{2}[A-Z]{5}\d{4}[A-Z][A-Z\d]Z[A-Z\d]$/.test(cGstin)) {
      return toast('Customer GSTIN format looks wrong');
    }

    const lines = salesState.lines.filter(l => l.n && (parseFloat(l.q) || 0) > 0 && (parseFloat(l.r) || 0) >= 0);
    if (!lines.length) return toast('Add at least one item with valid quantity and rate');

    const disc = parseFloat($('#pd_disc')?.value) || 0;
    const rate = parseFloat($('#pd_rate')?.value) || 0;
    const modeSel = $('#pd_mode')?.value || 'auto';
    const effMode = getMode(cState, modeSel, rate, cGstin);
    const payReceived = Boolean($('#pd_pay_received')?.checked);
    const paidAmt = payReceived ? (parseFloat($('#pd_paid')?.value) || 0) : 0;
    const pm = $('#pd_pm')?.value || 'Cash';
    const depositAcct = $('#pd_deposit_acct')?.value || (pm === 'Cash' ? '1000' : '1010');
    const payRef = ($('#pd_pay_ref')?.value || '').trim();
    const nt = ($('#pd_nt')?.value || '').trim();

    const f = calcFigs({ lines, disc, rate, mode: effMode, paid: paidAmt });
    const totalPaisa = f.gt * 100;
    const basePaisa = Math.round(f.tx * 100);
    const gstPaisa = Math.round(f.tax * 100);

    // Find or create customer in db.parties
    let party = salesState.selectedPartyId ? db.parties.find(p => p.id === salesState.selectedPartyId) : null;
    if (!party) {
      party = db.parties.find(p => p.name.trim().toLowerCase() === cName.toLowerCase() && isC(p));
    }
    if (!party) {
      party = {
        id: uid(),
        name: cName,
        type: 'customer',
        phone: cPhone,
        gstin: cGstin,
        state: cState,
        addr: cAddr,
        terms: '0'
      };
      db.parties.push(party);
    } else {
      if (cName) party.name = cName;
      if (cPhone) party.phone = cPhone;
      if (cGstin) party.gstin = cGstin;
      if (cState) party.state = cState;
      if (cAddr) party.addr = cAddr;
    }

    // Check if editing or new
    const isEditMode = Boolean(salesState.editNo);
    let existingDoc = isEditMode ? db.docs.find(d => d.no === salesState.editNo && d.type === 'sale') : null;
    if (!existingDoc && !isEditMode) {
      existingDoc = db.docs.find(d => d.no === no && d.type === 'sale');
    }

    if (!existingDoc && db.docs.some(d => d.no === no && d.type === 'sale')) {
      return toast('Invoice number ' + no + ' is already used');
    }

    // Party credit limit validation (TC-PARTY-01)
    if (party && party.limit) {
      const currentDues = db.docs
        .filter(d => d.party === party.id && d.type === 'sale' && !d.cancelled && (!existingDoc || d.id !== existingDoc.id))
        .reduce((sum, d) => sum + out(d), 0);
      const uncollectedAmt = Math.max(0, totalPaisa - Math.round(paidAmt * 100));
      if ((currentDues + uncollectedAmt) > party.limit) {
        const proceed = confirm(`Credit limit exceeded for this party (${fmt(party.limit)}). Current dues + this invoice: ${fmt(currentDues + uncollectedAmt)}. Proceed with authorization?`);
        if (!proceed) return;
      }
    }

    // Compute sales double-entry journal entry lines
    // Debit: 1100 Accounts Receivable (for totalPaisa)
    // Credit: 4000 Sales Revenue (for basePaisa)
    // Credit: 2200 Output GST (for gstPaisa) if gst > 0
    // Difference (roundoff): adjust against 4000 or 5600
    const diff = totalPaisa - (basePaisa + gstPaisa);
    const jLines = [
      { a: '1100', d: totalPaisa, c: 0, p: party.id },
      { a: '4000', d: 0, c: basePaisa + (diff > 0 ? diff : 0), p: party.id }
    ];
    if (gstPaisa > 0) {
      jLines.push({ a: '2200', d: 0, c: gstPaisa });
    }
    if (diff < 0) {
      jLines.push({ a: '5600', d: Math.abs(diff), c: 0, p: party.id });
    }

    let jeId = null;
    if (existingDoc && existingDoc.je) {
      // UPSERT / UPDATE: Update existing journal entry in-place instead of creating a duplicate
      const existingJe = db.entries.find(e => e.id === existingDoc.je);
      if (existingJe) {
        existingJe.date = date;
        existingJe.narr = no + ' - ' + cName + ' (Scrap Sale)';
        existingJe.meta = { ...existingJe.meta, docNo: no, veh };
        existingJe.lines = jLines;
        jeId = existingJe.id;
      }
    }

    // If no existing JE found, post a new one
    if (!jeId) {
      const je = post({
        date,
        src: 'sale',
        narr: no + ' - ' + cName + ' (Scrap Sale)',
        meta: { docNo: no, veh },
        lines: jLines
      });
      jeId = je.id;
    }

    const docId = existingDoc ? existingDoc.id : uid();
    const docObj = existingDoc || {
      id: docId,
      type: 'sale',
      pays: []
    };

    docObj.no = no;
    docObj.date = date;
    docObj.due = date;
    docObj.party = party.id;
    docObj.sno = veh;
    docObj.desc = lines.map(l => l.n + ' (' + l.q + ' ' + l.u + ')').join(', ');
    docObj.base = basePaisa;
    docObj.gst = gstPaisa;
    docObj.rate = rate;
    docObj.tax = { cg: effMode === 'intra' ? Math.round(f.half * 100) : 0, sg: effMode === 'intra' ? Math.round(f.half * 100) : 0, ig: effMode === 'inter' ? gstPaisa : 0 };
    docObj.total = totalPaisa;
    docObj.je = jeId;
    docObj.veh = veh;
    docObj.disc = disc;
    docObj.mode = effMode;
    docObj.modeSel = modeSel;
    docObj.paid = paidAmt;
    docObj.pm = pm;
    docObj.payAcct = depositAcct;
    docObj.payRef = payRef;
    docObj.nt = nt;
    docObj.lines = lines;
    docObj.c = { n: cName, p: cPhone, g: cGstin, s: cState, a: cAddr };
    docObj.cancelled = false;

    // Handle upfront payment receipt entry if paid > 0, or clear if 0
    if (paidAmt > 0) {
      const paidPaisa = Math.min(Math.round(paidAmt * 100), totalPaisa);
      let pJeId = null;

      if (existingDoc && existingDoc.pays && existingDoc.pays.length && existingDoc.pays[0].je) {
        const existingPJe = db.entries.find(e => e.id === existingDoc.pays[0].je);
        if (existingPJe) {
          existingPJe.date = date;
          existingPJe.lines = [
            { a: depositAcct, d: paidPaisa, c: 0, p: party.id },
            { a: '1100', d: 0, c: paidPaisa, p: party.id }
          ];
          existingPJe.narr = `${party.name} - Receipt for Invoice ${no}`;
          existingPJe.meta = {
            ...existingPJe.meta,
            ref: payRef || no,
            docNo: no,
            party: party.id,
            partyName: party.name,
            acct: depositAcct,
            method: pm
          };
          existingDoc.pays[0].amt = paidPaisa;
          existingDoc.pays[0].date = date;
          existingDoc.pays[0].method = pm;
          existingDoc.pays[0].acct = depositAcct;
          pJeId = existingPJe.id;
        }
      }

      if (!pJeId) {
        const pJe = post({
          date,
          src: 'in',
          narr: `${party.name} - Receipt for Invoice ${no}`,
          meta: {
            ref: payRef || no,
            docNo: no,
            invoiceId: docId,
            party: party.id,
            partyName: party.name,
            acct: depositAcct,
            cat: '1100',
            method: pm,
            desc: `${lines.map(l => l.n + (l.q ? ' (' + l.q + ' ' + (l.u || 'kg') + ')' : '')).join(', ')}${veh ? ' · Veh: ' + veh : ''} - Invoice ${no}`
          },
          lines: [
            { a: depositAcct, d: paidPaisa, c: 0, p: party.id },
            { a: '1100', d: 0, c: paidPaisa, p: party.id }
          ]
        });
        docObj.pays = [{ je: pJe.id, amt: paidPaisa, date, method: pm, acct: depositAcct }];
      }
    } else {
      if (existingDoc && existingDoc.pays && existingDoc.pays.length && existingDoc.pays[0].je) {
        try { reverse(existingDoc.pays[0].je); } catch (e) { }
      }
      docObj.pays = [];
      docObj.paid = 0;
    }

    if (!existingDoc) {
      db.docs.push(docObj);
    }

    save();
    toast(isEditMode ? 'Invoice updated successfully' : 'Invoice saved successfully');

    // Post-Save Redirect: Automatically route back to Records tab
    salesState.tab = 'rec';
    salesState.editNo = null;
    salesState.selectedPartyId = null;
    salesState.lines = [];
    container.innerHTML = renderSales();
    bindSalesEvents();

    // Immediately open clean Print/Preview modal
    showInvoicePreviewModal(docObj);
  };

  const saveBtn = $('#pd_btn_save');
  if (saveBtn) saveBtn.onclick = handleSaveInvoice;

  const saveTopBtn = $('#pd_btn_save_top');
  if (saveTopBtn) saveTopBtn.onclick = handleSaveInvoice;

  // Records: Search filter (debounced 300ms for fluid mobile typing)
  const searchInput = $('#pd_search_q');
  if (searchInput) {
    searchInput.oninput = debounce(() => {
      salesState.q = searchInput.value;
      const tabRec = $('#pd-tab-rec');
      if (tabRec) {
        // re-render just tab content to preserve cursor
        container.innerHTML = renderSales();
        bindSalesEvents();
        const nInput = $('#pd_search_q');
        if (nInput) {
          nInput.focus();
          nInput.setSelectionRange(nInput.value.length, nInput.value.length);
        }
      }
    }, 300);
  }

  // Records: Export CSV
  const csvBtn = $('#pd_btn_csv');
  if (csvBtn) {
    csvBtn.onclick = () => {
      const sales = db.docs.filter(d => d.type === 'sale').reverse();
      const header = 'Invoice,Date,Customer,GSTIN,Vehicle,Taxable,Tax,Total,Received,Balance\n';
      const body = sales.map(d => {
        const f = calcFigs(d);
        return [
          d.no,
          d.date,
          d.c?.n || pn(d.party),
          d.c?.g || '',
          d.veh || '',
          f.tx.toFixed(2),
          f.tax.toFixed(2),
          f.gt.toFixed(2),
          (d.paid || 0).toFixed(2),
          f.bal.toFixed(2)
        ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(',');
      }).join('\n');

      downloadCSV(header + body, 'sales_invoices');
      toast('Sales Invoices CSV exported');
    };
  }

  // Records: Table Action Buttons (View, Edit, Pay, Delete)
  container.querySelectorAll('#pd-tab-rec button[data-action]').forEach(btn => {
    btn.onclick = () => {
      const action = btn.dataset.action;
      const no = btn.dataset.no;
      const doc = db.docs.find(d => d.no === no && d.type === 'sale');
      if (!doc) return;

      if (action === 'more') {
        const isPaid = doc.pays && doc.pays.length && doc.pays.reduce((s, p) => s + (p.a || 0), 0) >= (doc.total || 0);
        const sheetItems = [
          {
            label: 'View Invoice',
            variant: 'view',
            icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"></path><circle cx="12" cy="12" r="3"></circle></svg>`,
            onClick: () => showInvoicePreviewModal(doc)
          },
          {
            label: 'Edit Invoice',
            variant: 'edit',
            icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"></path></svg>`,
            onClick: () => {
              salesState.tab = 'new';
              salesState.editNo = no;
              salesState.selectedPartyId = doc.party || null;
              salesState.lines = doc.lines && doc.lines.length ? JSON.parse(JSON.stringify(doc.lines)) : [{ n: doc.desc || 'Scrap', h: '', q: 1, u: 'kg', r: doc.base / 100 }];
              container.innerHTML = renderSales();
              bindSalesEvents();
            }
          }
        ];
        if (!isPaid && !doc.cancelled) {
          sheetItems.push({
            label: 'Mark as Paid',
            variant: 'pay',
            icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="m9 12 2 2 4-4"></path></svg>`,
            onClick: () => {
              markSalePaid(doc, () => {
                container.innerHTML = renderSales();
                bindSalesEvents();
              });
            }
          });
        }
        sheetItems.push({
          label: 'Delete Invoice',
          variant: 'delete',
          danger: true,
          icon: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>`,
          onClick: () => {
            if (confirm(`Are you sure you want to delete invoice ${no}?`)) {
              if (doc.je) {
                try { reverse(doc.je); } catch (e) { console.warn('Could not reverse je:', e); }
              }
              if (doc.pays && doc.pays.length) {
                doc.pays.forEach(p => {
                  try { reverse(p.je); } catch (e) { }
                });
              }
              doc.cancelled = true;
              db.docs = db.docs.filter(d => d !== doc);
              save();
              toast('Invoice ' + no + ' deleted');
              container.innerHTML = renderSales();
              bindSalesEvents();
            }
          }
        });
        showActionSheet(`Invoice #${doc.no}`, `${esc(doc.c?.n || pn(doc.party))} • ${fmt(doc.total)}`, sheetItems);
        return;
      } else if (action === 'view') {
        showInvoicePreviewModal(doc);
      } else if (action === 'edit') {
        salesState.tab = 'new';
        salesState.editNo = no;
        salesState.selectedPartyId = doc.party || null;
        salesState.lines = doc.lines && doc.lines.length ? JSON.parse(JSON.stringify(doc.lines)) : [{ n: doc.desc || 'Scrap', h: '', q: 1, u: 'kg', r: doc.base / 100 }];
        container.innerHTML = renderSales();
        bindSalesEvents();
      } else if (action === 'pay') {
        // Mark paid with account selection (Cash vs Bank)
        markSalePaid(doc, () => {
          container.innerHTML = renderSales();
          bindSalesEvents();
        });
      } else if (action === 'del') {
        if (btn.dataset.confirmed) {
          // Cancel doc and reverse journal entry
          if (doc.je) {
            try { reverse(doc.je); } catch (e) { console.warn('Could not reverse je:', e); }
          }
          if (doc.pays && doc.pays.length) {
            doc.pays.forEach(p => {
              try { reverse(p.je); } catch (e) { }
            });
          }
          doc.cancelled = true;
          db.docs = db.docs.filter(d => d !== doc);
          save();
          toast('Invoice ' + no + ' deleted');
          container.innerHTML = renderSales();
          bindSalesEvents();
        } else {
          btn.dataset.confirmed = '1';
          btn.textContent = 'Confirm?';
          setTimeout(() => {
            btn.textContent = 'Delete';
            delete btn.dataset.confirmed;
          }, 3000);
        }
      }
    };
  });

  // Scrap items: Add item row
  const addItemBtn = $('#pd_btn_add_item');
  if (addItemBtn) {
    addItemBtn.onclick = () => {
      if (!db.items) db.items = [];
      db.items.push({ n: '', h: '7204', u: 'kg', r: 0 });
      const tbody = $('#pd_items_body');
      if (tbody) {
        const i = db.items.length - 1;
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td data-label="Item"><input type="text" class="pd-item-n" data-i="${i}" value=""></td>
          <td data-label="HSN"><input type="text" class="pd-item-h" data-i="${i}" value="7204"></td>
          <td data-label="Unit">
            <select class="pd-item-u" data-i="${i}">
              <option value="kg" selected>kg</option>
              <option value="quintal">quintal</option>
              <option value="ton">ton</option>
              <option value="pcs">pcs</option>
            </select>
          </td>
          <td data-label="Rate (₹)"><input type="number" step="any" class="pd-item-r" data-i="${i}" value="0"></td>
          <td data-label="Actions"><button type="button" class="btn red sm pd-item-del" data-i="${i}" title="Remove item" aria-label="Remove item"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="pointer-events:none"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></button></td>
        `;
        tbody.appendChild(tr);
        bindSalesEvents();
        const newInp = tr.querySelector('.pd-item-n');
        if (newInp) {
          newInp.focus();
          newInp.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }
    };
  }

  // Master Scrap items: auto-convert default rate on unit change
  container.querySelectorAll('#pd_items_body .pd-item-u').forEach(unitSel => {
    unitSel.dataset.prevUnit = unitSel.value;
    unitSel.onchange = e => {
      const tr = e.target.closest('tr');
      if (!tr) return;
      const newUnit = e.target.value;
      const prevUnit = unitSel.dataset.prevUnit || 'kg';
      const rateInput = tr.querySelector('.pd-item-r');
      const curRate = parseFloat(rateInput?.value) || 0;
      if (curRate > 0) {
        rateInput.value = convertRate(curRate, prevUnit, newUnit);
      }
      unitSel.dataset.prevUnit = newUnit;
    };
  });

  // Scrap items: Delete row
  container.querySelectorAll('.pd-item-del').forEach(btn => {
    btn.onclick = () => {
      const idx = parseInt(btn.dataset.i, 10);
      if (!isNaN(idx) && db.items) {
        db.items.splice(idx, 1);
        container.innerHTML = renderSales();
        bindSalesEvents();
      }
    };
  });

  // Scrap items: Save items catalog
  const saveItemsBtn = $('#pd_btn_save_items');
  if (saveItemsBtn) {
    saveItemsBtn.onclick = () => {
      const items = [];
      container.querySelectorAll('#pd_items_body tr').forEach(tr => {
        const n = (tr.querySelector('.pd-item-n')?.value || '').trim();
        const h = (tr.querySelector('.pd-item-h')?.value || '').trim();
        const u = tr.querySelector('.pd-item-u')?.value || 'kg';
        const r = parseFloat(tr.querySelector('.pd-item-r')?.value) || 0;
        if (n) items.push({ n, h, u, r });
      });
      db.items = items;
      save();
      toast('Scrap items saved');
    };
  }

  // View mode: Back to records
  const backBtn = $('#pd_btn_back');
  if (backBtn) {
    backBtn.onclick = () => {
      salesState.tab = 'rec';
      container.innerHTML = renderSales();
      bindSalesEvents();
    };
  }

  // View mode: Print
  const printBtn = $('#pd_btn_print');
  if (printBtn) {
    printBtn.onclick = () => {
      window.print();
    };
  }

  // View mode: Download HTML
  const dHtmlBtn = $('#pd_btn_dhtml');
  if (dHtmlBtn) {
    dHtmlBtn.onclick = () => {
      const doc = db.docs.find(d => d.no === salesState.viewNo && d.type === 'sale');
      if (!doc) return;
      const content = renderSheet(doc);
      const fullHtml = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Invoice ${esc(doc.no)}</title>
<style>
body { margin: 0; background: #f6f8f9; font-family: "Segoe UI", system-ui, -apple-system, sans-serif; }
${$('#pd-sheet-css')?.textContent || ''}
.sheet { position: relative; background: #fff !important; color: #111 !important; width: 210mm; min-height: 297mm; padding: 14mm; margin: 20px auto; font-size: 12.5px; border: 1px solid #ccc; box-sizing: border-box; overflow: hidden; }
.sheet * { color: #111; box-sizing: border-box; }
.wm { position: absolute; left: 50%; top: 50%; width: 60%; transform: translate(-50%, -50%); opacity: .07; mix-blend-mode: multiply; pointer-events: none; }
.sh { display: flex; gap: 16px; align-items: center; border-bottom: 3px solid #04a9a5; padding-bottom: 12px; }
.sh img { height: 64px; }
.logo-badge { width: 64px; height: 64px; border-radius: 12px; background: #066c80; color: #fff !important; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 24px; flex-shrink: 0; }
.tbl-scroll { overflow-x: auto; }
.sh h1 { margin: 0 0 4px; font-size: 24px; color: #066c80; }
.ttl { text-align: center; font-weight: 700; font-size: 16px; letter-spacing: 1px; margin: 14px 0 10px; color: #121c22; }
.two { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.box { border: 1px solid #99aaaa; padding: 8px 10px; min-height: 80px; border-radius: 4px; font-size: 12px; line-height: 1.45; }
table { width: 100%; margin: 12px 0; border-collapse: collapse; }
th { background: #121c22 !important; color: #ffffff !important; font-size: 12px; font-weight: 600; padding: 6px 8px; border: 1px solid #99aaaa; text-align: left; }
td { border: 1px solid #99aaaa; padding: 6px 8px; font-size: 12px; }
.r { text-align: right; }
.tot { margin-left: auto; max-width: 300px; margin-top: 10px; }
.tot div { display: flex; justify-content: space-between; padding: 3px 0; font-size: 13px; }
.tot .gt { font-weight: 700; font-size: 15px; border-top: 2px solid #04a9a5; padding-top: 6px; }
.sign { display: flex; justify-content: space-between; margin-top: 48px; font-size: 12px; }
@media print { @page { size: A4; margin: 0; } .sheet { border: 0; margin: 0; } }
</style>
</head>
<body>
${content}
</body>
</html>`;
      const blob = new Blob([fullHtml], { type: 'text/html' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = ('Invoice_' + doc.no + '_' + (doc.c?.n || 'Customer')).replace(/[^\w.-]+/g, '_') + '.html';
      a.click();
      toast('HTML file downloaded');
    };
  }

  // View mode: Download PDF
  const dPdfBtn = $('#pd_btn_dpdf');
  if (dPdfBtn) {
    dPdfBtn.onclick = () => {
      const doc = db.docs.find(d => d.no === salesState.viewNo && d.type === 'sale');
      if (!doc) return;
      try {
        const p = mkPdf(doc);
        const name = ('Invoice_' + doc.no + '_' + (doc.c?.n || 'Customer')).replace(/[^\w.-]+/g, '_') + '.pdf';
        p.save(name);
        toast('PDF downloaded');
      } catch (e) {
        console.error(e);
        toast('PDF error: ' + (e.message || e));
      }
    };
  }
}
